#include <iostream>
#include <vector>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long w, m;
    cin >> w >> m;

    vector<long long> sum(105, 0);
    vector<long long> pw(105, 0);
    bool result = false;

    long long p = 1;
    int maxIndex = 0;
    for (int i = 0; i < 100; i++) {
        sum[i + 1] = sum[i] + p;
        pw[i] = p;
        p *= w;
        if (p > (1LL << 40)) {
            maxIndex = i;
            break;
        }
    }

    function<void(long long, long long, int)> checkPossibility = [&](long long current, long long target, int position) {
        if (result) return;
        if (current == target) {
            result = true;
            return;
        }
        long long remainingSum = sum[position + 1];
        long long powerVal = pw[position];

        if (current - remainingSum > target || current + remainingSum < target) {
            return;
        }

        if (current + sum[position] < target) {
            checkPossibility(current + powerVal, target, position - 1);
        } else if (current - sum[position] > target) {
            checkPossibility(current - powerVal, target, position - 1);
        } else {
            checkPossibility(current, target, position - 1);
        }
    };

    checkPossibility(0, m, maxIndex);
    cout << (result ? "YES" : "NO") << "\n";

    return 0;
}
